package game

import (
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"testing"
)

// Actual native receipts are regenerated by --awake-clock-core-only.
// This compares domain clocks. State/save/GUI integration is verified by the
// separate integration consumer and normal-player tests.
func TestExportTalosAwakeClockCore(t *testing.T) {
	root := os.Getenv("SUNDOG_AWAKE_CLOCK_NATIVE")
	if root == "" {
		t.Skip("fresh native clock receipts absent")
	}
	read := func(folder, file string, target any) {
		data, err := os.ReadFile(filepath.Join(root, folder, file))
		if err != nil {
			t.Fatal(err)
		}
		if err := json.Unmarshal(data, target); err != nil {
			t.Fatal(err)
		}
	}
	report := struct {
		PlatformCases, BackgroundCases, PauseCases, GroundCases, Differences int
		Scope                                                                string
	}{Scope: "typed core VBL/event/worker/slot/deadline; this comparison excludes GUI, new-game interleave and State/library integration"}
	var platform struct {
		Rows []struct {
			Before, After           uint32
			Enabled                 bool
			VBLs, Events, Countdown int
			TimeBefore, TimeAfter   [2]int
		}
	}
	read("platform", "native-food-platform-clock.json", &platform)
	for _, row := range platform.Rows {
		c := VBLClock{Ticks: row.Before}
		c.Enable(row.Enabled)
		events := 0
		for i := 0; i < row.VBLs; i++ {
			if c.Advance() {
				events++
			}
		}
		before := [2]int{int(row.Before >> 16), int(row.Before & 65535)}
		after := [2]int{int(c.Ticks >> 16), int(c.Ticks & 65535)}
		if c.Ticks != row.After || events != row.Events || int(uint16(c.EventCountdown)) != row.Countdown || before != row.TimeBefore || after != row.TimeAfter {
			report.Differences++
		}
		report.PlatformCases++
	}
	var background struct {
		Rows []struct {
			Location, Phase, Passes int
			SlotsBefore, SlotsAfter [2][3]int
			Trace                   struct {
				Pulses, Passes int
				Callbacks      [][3]int
			}
		}
	}
	read("background", "native-food-awake-background.json", &background)
	for _, row := range background.Rows {
		c := BackgroundClock{}
		for i, v := range row.SlotsBefore {
			c.Slots[i] = ClockSlot{Callback: ClockCallback(v[0]), Remaining: v[1], Period: v[2]}
		}
		if row.Phase < 0 {
			// This input is the native receipt's controlled interleaving.
			c.BeginPass()
			if err := c.Start(ClockMinute, 60); err != nil {
				t.Fatal(err)
			}
			if row.Location == 2 {
				if err := c.Start(ClockIdleShip, 30); err != nil {
					t.Fatal(err)
				}
			}
		}
		pulses, passes := 0, 0
		var callbacks [][3]int
		for passes < row.Passes && pulses < 70000 {
			pulses++
			if c.AdvanceEvent(func(id ClockCallback) { callbacks = append(callbacks, [3]int{passes + 1, pulses, int(id)}) }) {
				passes++
			}
		}
		var slots [2][3]int
		for i := range slots {
			v := c.Slots[i]
			slots[i] = [3]int{int(v.Callback), v.Remaining, v.Period}
		}
		if slots != row.SlotsAfter || pulses != row.Trace.Pulses || passes != row.Trace.Passes || !reflect.DeepEqual(callbacks, row.Trace.Callbacks) {
			report.Differences++
		}
		report.BackgroundCases++
	}
	var pause struct {
		Rows []struct {
			PausedCallback, SavedPeriod int
			Before, Paused, After       [8][3]int
		}
	}
	read("pause", "native-food-scene-clock-pause.json", &pause)
	for _, row := range pause.Rows {
		c := BackgroundClock{WaitEvents: 5}
		for i, v := range row.Before {
			c.Slots[i] = ClockSlot{ClockCallback(v[0]), v[1], v[2]}
		}
		id := ClockCallback(row.PausedCallback)
		saved := c.PeriodTicks(id)
		c.Stop(id)
		asArray := func() (v [8][3]int) {
			for i, s := range c.Slots {
				v[i] = [3]int{int(s.Callback), s.Remaining, s.Period}
			}
			return
		}
		ok := saved == row.SavedPeriod && asArray() == row.Paused
		if err := c.Start(id, saved); err != nil {
			t.Fatal(err)
		}
		if !ok || asArray() != row.After || c.WaitEvents != 5 {
			report.Differences++
		}
		report.PauseCases++
	}
	var ground struct {
		Wide []struct {
			Left, Right [2]int
			Gate        int
		}
		Deadlines []struct {
			Before, After [2]int
			Delta         int
		}
		Ground []struct {
			Foot                                                    bool
			Record5, CounterBefore, CounterAfter, NowDelta, Applied int
			DeadlineAfter                                           [2]int
		}
	}
	read("ground", "native-food-ground-clock.json", &ground)
	timestamp := func(v [2]int) uint32 { return uint32(v[0])<<16 | uint32(v[1]) }
	for _, row := range ground.Wide {
		if GroundTimeReady(timestamp(row.Left), timestamp(row.Right)) != (row.Gate == 1) {
			report.Differences++
		}
		report.GroundCases++
	}
	for _, row := range ground.Deadlines {
		c := GroundClock{}
		if err := c.Reset(timestamp(row.Before), uint16(row.Delta)); err != nil {
			t.Fatal(err)
		}
		if c.Deadline != timestamp(row.After) {
			report.Differences++
		}
		report.GroundCases++
	}
	for _, row := range ground.Ground {
		c := GroundClock{Deadline: 100, Updates: row.CounterBefore}
		minutes := c.Update(uint32(100+row.NowDelta), row.Record5 == 1, row.Foot)
		if minutes != row.Applied || c.Updates != row.CounterAfter || c.Deadline != timestamp(row.DeadlineAfter) {
			report.Differences++
		}
		report.GroundCases++
	}
	if [4]int{report.PlatformCases, report.BackgroundCases, report.PauseCases, report.GroundCases} != [4]int{36, 241, 72, 937} {
		t.Fatalf("incomplete native comparison: %+v", report)
	}
	data, err := json.MarshalIndent(report, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(root, "remake-awake-clock-core.json"), append(data, '\n'), 0600); err != nil {
		t.Fatal(err)
	}
	if report.Differences != 0 {
		t.Fatalf("native clock core differences: %+v", report)
	}
}
